def solution(input_str):
    import sys
    from io import StringIO

    input_data = StringIO(input_str)

    def parse_tree():
        t_line = input_data.readline().strip()
        while t_line == '':
            t_line = input_data.readline().strip()
        t = int(t_line)

        results = []

        for _ in range(t):
            empty_line = input_data.readline()  # empty line
            n = int(input_data.readline().strip())

            children = []
            for _ in range(n):
                parts = input_data.readline().strip().split()
                if parts[0] == '-1':
                    children.append({'type': 'internal', 'left': int(parts[1]), 'right': int(parts[2])})
                else:
                    children.append({'type': 'leaf', 'value': int(parts[0])})

            results.append(solve_tree(children))

        return '\n'.join(results)

    def solve_tree(children):
        if children[0]['type'] == 'leaf':
            return children[0]['value']

        # For a full binary tree - calculate the result
        # Use dynamic programming with memoization based on subtree structure
        # Each internal node needs to consider the game-theoretic value

        # For each internal node, count leaves in subtree
        def count_leaves(node_idx):
            if children[node_idx]['type'] == 'leaf':
                return 1
            return count_leaves(children[node_idx]['left']) + count_leaves(children[node_idx]['right'])

        def compute_value(node_idx, is_max_player_turn):
            """
            Returns the game value for subtree rooted at node_idx
            is_max_player_turn: True if current player wants to maximize
            """
            if children[node_idx]['type'] == 'leaf':
                return children[node_idx]['value']

            left_val = compute_value(children[node_idx]['left'], is_max_player_turn)
            right_val = compute_value(children[node_idx]['right'], is_max_player_turn)

            total_leaves = count_leaves(node_idx)
            # If total leaves is even, current turn player makes the final merge
            # If odd, previous turn player makes the final merge
            # This determines who controls the final choice

            # For this problem structure (full binary tree), cada merge reduces leaves by 1
            # With n leaves, n-1 merges total
            # Pieguy goes first

            # The key is: at each internal node, if we have odd leaf subcount, 
            # the "max player" controls this internal node's final choice

            if total_leaves % 2 == 1:
                # Odd - Pieguy (maximizing) at this node's final merge
                return max(left_val, right_val)
            else:
                # Even - Piegirl (minimizing) at this node's final merge
                return min(left_val, right_val)

        return compute_value(0, True)

    return parse_tree()

