            adj[v].append((u, i))

        # BFS to check if s can reach t given removed edges
        def is_connected(removed_edges):
            visited = {s}
            queue = [s]
            head = 0

            while head < len(queue):
                curr = queue[head]
                head += 1

                if curr == t:
                    return True

                for neighbor, idx in adj[curr]:
                    if idx in removed_edges:
                        continue
                    if neighbor not in visited:
                        visited.add(neighbor)
