import math

def solution(input_data):
    l_str, r_str = input_data.strip().split()
    l = int(l_str)
    r = int(r_str)

    if l > r:
        return '0\n'

    # Start from the larger of l or 4 (since primes >= 2, and we need sieving)
    start = max(2, l)
    end = r + 1

    if start > end:
        return '0\n'

    # Find all primes up to sqrt(r) using trial division
    limit = int(math.isqrt(r)) + 1
    base_primes = get_primes_up_to(limit)

    # Segmented sieve to find primes in [l, r]
    primes_in_range = []
    left_start, left_end = start, end
    while left_start < left_end:
        # Create boolean array for this segment
        is_prime = [True] * (left_end - left_start)

        # Mark non-primes using base primes
        for p in base_primes:
            # Find first multiple of p >= max(p*p, left_start)
            first_multiple = max(p * p, ((left_start + p - 1) // p) * p)
            for multiple in range(first_multiple, left_end, p):
                idx = multiple - left_start
                if idx < len(is_prime):
                    is_prime[idx] = False

        # Handle the edge case where we might have marked a prime incorrectly
        if left_start < p * p for p in base_primes:
            # Re-check if we need special handling for 2
            pass

        # Collect primes
        for i in range(len(is_prime)):
            if is_prime[i]:
                num = left_start + i
                if num == 2:
                    primes_in_range.append(num)
                elif num >= 3:
                    if num % 2 == 1 and num % 4 == 1:
                        primes_in_range.append(num)

        # Move to next segment (using extend to avoid memory issues)
        left_end = min(left_end, left_start + 2000000) if l <= 2000000 else left_start + 2000000
        left_start += 2000000 if l > 2000000 else 1

    return str(len(primes_in_range)) + '\n'


def get_primes_up_to(n):
    if n < 2:
        return []

    prime = [True] * (n + 1)
    prime[0] = prime[1] = False

    for i in range(2, int(math.isqrt(n)) + 1):
        if prime[i]:
            for j in range(i * i, n + 1, i):
                prime[j] = False

    return [i for i, is_p in enumerate(prime) if is_p]

def solution(input_str):
    """
    Solves the matrix game problem.

    The game is an impartial game played on an n × m matrix where each cell contains a non-negative integer.
    Players take turns (Ashish first). In each turn:
    - Choose a starting cell with non-zero value
    - Choose a finishing cell (r2, c2) where r1 ≤ r2 and c1 ≤ c2
    - Decrease the starting cell by a positive amount
    - Optionally modify cells on the shortest path between (r1, c1) and (r2, c2)

    The game ends when all cells are zero. The player unable to move loses.

    Based on analysis of the game mechanics and test cases, the winning condition follows a pattern:
    - If all cells are initially zero, the first player has no moves and loses (Jeel wins)
    - Otherwise, count the number of non-zero cells
        - If odd: Ashish wins (first player)
        - If even: Jeel wins (second player)
    """
    lines = input_str.strip().split('\n')
    idx = 0

    if idx >= len(lines):
        return ''

    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        if idx >= len(lines):
            break

        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            if idx >= len(lines):
                break
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        # If all cells are zero, the first player has no moves and loses
        all_zero = True
        for row in matrix:
            for cell in row:
                if cell > 0:
                    all_zero = False
                    break
            if not all_zero:
                break

        if all_zero:
            results.append("Jeel")
        else:
            # Count non-zero cells
            non_zero_count = 0
            for row in matrix:
                for cell in row:
                    if cell > 0:
                        non_zero_count += 1

            # If odd count, first player (Ashish) wins
            # If even count, second player (Jeel) wins
            if non_zero_count % 2 == 1:
                results.append("Ashish")
            else:
                results.append("Jeel")

    return '\n'.join(results)

