def segments_intersect(p1, p2, p3, p4):
    """Check if line segments p1-p2 and p3-p4 intersect (but not at endpoints)."""
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    cp1 = cross_product(p1, p2, p3)
    cp2 = cross_product(p1, p2, p4)
    if cp1 == 0 or cp2 == 0:
        return False
    cp3 = cross_product(p3, p4, p1)
    cp4 = cross_product(p3, p4, p2)
    if cp3 == 0 or cp4 == 0:
        return False
    return (cp1 > 0) != (cp2 > 0) and (cp3 > 0) != (cp4 > 0)

