    temp = m
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def find_primitive_root(p):
    """Find a primitive root modulo prime p"""
    if p == 2:
        return 1

    fp1 = p - 1
    prime_factors = set()
    temp = fp1

    d = 2
    while d * d <= temp:
        if temp % d == 0:
            prime_factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        prime_factors.add(temp)

    for g in range(2, p):
        is_primitive = True
        for q in prime_factors:
            if pow(g, fp1 // q, p) == 1:
                is_primitive = False
                break
        if is_primitive:
            return g

